edits.replacement_template:
qualifying_events = {
    1: (2475, 2585, 41),
    2: (1210, 1300, 24),
    3: (1760, 1825, 15),
}
qualifying_event_id = {value}
qualifying_low, qualifying_high, qualifying_baseline_ticks = (
    qualifying_events[qualifying_event_id]
)
qualifying_in_event = (
    qualifying_low <= self.current_waypoint_idx <= qualifying_high
)
if not qualifying_in_event:
    self._qualifying_brake_ordinal = 0
    self._qualifying_last_release_suppression_tick = None
    qualifying_event_state = "outside"
else:
    qualifying_event_state = "armed"

qualifying_raw_brake = float(brake)
qualifying_suppressed = False
qualifying_suppression_reason = ""
qualifying_rerequest = False
qualifying_released_ticks_before_rerequest = None
if qualifying_in_event and qualifying_raw_brake > 0:
    self._qualifying_brake_ordinal = (
        getattr(self, "_qualifying_brake_ordinal", 0) + 1
    )
    qualifying_ordinal = self._qualifying_brake_ordinal
    qualifying_last_suppression = getattr(
        self, "_qualifying_last_release_suppression_tick", None
    )
    if qualifying_last_suppression is not None:
        qualifying_rerequest = True
        qualifying_released_ticks_before_rerequest = max(
            0, self.num_ticks - qualifying_last_suppression - 1
        )
    if qualifying_ordinal <= self._qualifying_onset_delay_ticks:
        qualifying_suppressed = True
        qualifying_suppression_reason = "onset-delay"
        qualifying_event_state = "onset-delay-suppressed"
    elif (
        qualifying_baseline_ticks - self._qualifying_release_early_ticks
        < qualifying_ordinal <= qualifying_baseline_ticks
    ):
        qualifying_suppressed = True
        qualifying_suppression_reason = "early-release"
        qualifying_event_state = "early-release-suppressed"
        if qualifying_rerequest:
            if qualifying_released_ticks_before_rerequest == 0:
                qualifying_event_state += "-rerequest-immediate"
            else:
                qualifying_event_state += "-rerequest-delayed"
        self._qualifying_last_release_suppression_tick = self.num_ticks
    elif qualifying_rerequest:
        qualifying_event_state = (
            "brake-rerequest-immediate"
            if qualifying_released_ticks_before_rerequest == 0
            else "brake-rerequest-delayed"
        )
    else:
        qualifying_event_state = "braking"
    if qualifying_suppressed:
        throttle = 0.0
        brake = 0.0
        gear = max(1, int(current_speed_kmh / 60))
elif qualifying_in_event:
    qualifying_ordinal = getattr(self, "_qualifying_brake_ordinal", 0)
    if getattr(self, "_qualifying_last_release_suppression_tick", None) is not None:
        qualifying_event_state = "released"
else:
    qualifying_ordinal = 0

if self.throttle_controller.last_longitudinal_debug:
    self.throttle_controller.last_longitudinal_debug.update(
        {
            "override_selected_event": qualifying_event_id,
            "override_onset_delay_ticks": self._qualifying_onset_delay_ticks,
            "override_release_early_ticks": self._qualifying_release_early_ticks,
            "override_raw_winner_brake": qualifying_raw_brake,
            "override_applied_brake": float(brake),
            "override_tick_suppressed": qualifying_suppressed,
            "override_suppression_reason": qualifying_suppression_reason,
            "override_brake_ordinal": qualifying_ordinal,
            "override_event_state": qualifying_event_state,
            "override_brake_rerequest": qualifying_rerequest,
            "override_released_ticks_before_rerequest": qualifying_released_ticks_before_rerequest,
        }
    )

steerMultiplier = round((current_speed_kmh + 0.001) / 120, 3)

causal.wp1779_1803_suppress_brake_ticks.replacement_template:
if not 1779 <= self.current_waypoint_idx <= 1803:
    self._wp1799_suppressed_brake_ticks = 0
elif (
    brake > 0
    and getattr(self, "_wp1799_suppressed_brake_ticks", 0) < {value}
):
    throttle = 0.0
    brake = 0.0
    gear = max(1, int(current_speed_kmh / 60))
    self._wp1799_suppressed_brake_ticks = (
        getattr(self, "_wp1799_suppressed_brake_ticks", 0) + 1
    )

steerMultiplier = round((current_speed_kmh + 0.001) / 120, 3)

